	"bufio"
	"fmt"
	"os"
)

const M int64 = 1_000_000_007

type Co struct {
	v int64
}

func NewCoFromInt64(value int64) Co {
	x := value % M
	if x < 0 {
		x += M
	}
	return Co{x}
}

func NewCoFromInt(value int) Co {
	return NewCoFromInt64(int64(value))
}

func (c Co) Add(other Co) Co {
	return NewCoFromInt64(c.v + other.v)
}

func (c *Co) AddAssign(other Co) {
	*c = c.Add(other)
}

func (c Co) Sub(other Co) Co {
	return NewCoFromInt64(c.v - other.v)
}

func (c *Co) SubAssign(other Co) {
	*c = c.Sub(other)
